    val customers by vm.customers.collectAsState(); val current = customers.firstOrNull { it.id == customerId } ?: return; var name by remember(current) { mutableStateOf(current.name) }; var phone by remember(current) { mutableStateOf(current.phone) }; var address by remember(current) { mutableStateOf(current.address) }; var note by remember(current) { mutableStateOf(current.note) }; var selected by remember(current) { mutableStateOf(current.deliveryDay) }; val scope = rememberCoroutineScope()
    PremiumPage { PremiumPageTitle("Customer Detail", "Edit customer information"); ColdDeliveryCard { Column(Modifier.padding(11.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Field(name, { name = it }, "Name"); Field(phone, { phone = it }, "Phone", KeyboardType.Phone); Field(address, { address = it }, "Address"); Select("Delivery day", selected.name) { DeliveryDay.values().forEach { d -> DropdownMenuItem(text = { Text(d.name) }, onClick = { selected = d }) } }; Field(note, { note = it }, "Note") } }; Text("Sort order  " + current.sortOrder, color = Gold, fontSize = 11.sp); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { PremiumOutlinedButton("Move up", { scope.launch { vm.moveCustomer(customerId, -1) } }, Modifier.weight(1f)); PremiumOutlinedButton("Move down", { scope.launch { vm.moveCustomer(customerId, 1) } }, Modifier.weight(1f)) }; Spacer(Modifier.weight(1f)); TextButton({ scope.launch { vm.updateCustomer(current.copy(isActive = false)); onSaved() } }) { Text("Archive customer", color = DeepRed, fontSize = 11.sp) }; PrimaryRedButton("Save Changes", { scope.launch { vm.updateCustomer(current.copy(name = name, phone = phone, address = address, note = note, deliveryDay = selected)); onSaved() } }, Modifier.fillMaxWidth()) }
}

