@Composable fun ProductDetailScreen(productId: Long, vm: FeatureViewModel = hiltViewModel()) {
    val products by vm.products.collectAsState(); val product = products.firstOrNull { it.id == productId }; var total by remember { mutableStateOf(0) }; var batches by remember { mutableStateOf(emptyList<StockBatchEntity>()) }; LaunchedEffect(productId) { total = vm.stockTotal(productId); batches = vm.stockBatches(productId) }
    PremiumPage { PremiumPageTitle(product?.productName ?: "Product", product?.productCode ?: ""); ColdDeliveryCard { Row(Modifier.fillMaxWidth().padding(12.dp), horizontalArrangement = Arrangement.SpaceBetween) { Column { Text("Total stock", color = ColdDeliveryColors.SecondaryText, fontSize = 10.sp); Text("$total CTN", color = if (total == 0) DeepRed else DeliveredGreen, fontSize = 22.sp, fontWeight = FontWeight.Bold) }; Text("FIFO • oldest first", color = Gold, fontSize = 11.sp) } }; Text("FIFO batches", color = DeepRed, fontWeight = FontWeight.Bold); LazyColumn(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(8.dp)) { items(batches, key = { it.id }) { b -> ColdDeliveryCard { Column(Modifier.padding(12.dp)) { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { Text("Stock in " + day(b.stockInDate), fontWeight = FontWeight.Bold, fontSize = 13.sp); Text(if (b.remainingQty == 0) "CONSUMED" else "ACTIVE", color = if (b.remainingQty == 0) DeepRed else DeliveredGreen, fontSize = 10.sp, fontWeight = FontWeight.Bold) }; Text("Initial  " + b.initialQty + " CTN    Remaining  " + b.remainingQty + " CTN", color = ColdDeliveryColors.SecondaryText, fontSize = 11.sp) } } } } }
}

@Composable fun EditDeliveryScreen(deliveryId: Long, onSaved: () -> Unit, vm: FeatureViewModel = hiltViewModel()) {
    val products by vm.products.collectAsState(); var customerName by remember { mutableStateOf("") }; var lines by remember { mutableStateOf<List<Pair<Long, String>>>(emptyList()) }; var error by remember { mutableStateOf<String?>(null) }; val scope = rememberCoroutineScope(); LaunchedEffect(deliveryId) { vm.delivery(deliveryId)?.let { d -> customerName = vm.customer(d.customerId)?.name ?: ""; lines = vm.items(deliveryId).map { it.productId to it.qty.toString() } } }
    PremiumPage { PremiumPageTitle("Edit Delivery", "Update this delivery record"); ColdDeliveryCard { Row(Modifier.fillMaxWidth().padding(12.dp), horizontalArrangement = Arrangement.SpaceBetween) { Text(customerName, fontSize = 15.sp, fontWeight = FontWeight.Bold); Text("Delivery #" + deliveryId, color = Gold, fontSize = 11.sp) } }; error?.let { Text(it, color = DeepRed, fontSize = 11.sp) }; LazyColumn(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(8.dp)) { items(lines, key = { it.first }) { line -> ColdDeliveryCard { Row(Modifier.fillMaxWidth().padding(11.dp), verticalAlignment = Alignment.CenterVertically) { Text(products.firstOrNull { it.id == line.first }?.productName ?: "Product", Modifier.weight(1f), fontSize = 13.sp, fontWeight = FontWeight.Bold); Field(line.second, { v -> lines = lines.map { if (it.first == line.first) line.first to v.filter(Char::isDigit) else it } }, "CTN", KeyboardType.Number, Modifier.width(108.dp)); TextButton({ lines = lines.filterNot { it.first == line.first } }) { Text("Remove", color = DeepRed, fontSize = 10.sp) } } } } }; TextButton({ products.firstOrNull { p -> lines.none { it.first == p.id } }?.let { lines = lines + (it.id to "1") } }) { Text("+ Add Product", color = DeepRed, fontSize = 12.sp) }; PrimaryRedButton("Save Changes", { scope.launch { try { vm.edit(deliveryId, lines.map { it.first to (it.second.toIntOrNull() ?: 0) }); onSaved() } catch (t: Throwable) { error = t.message ?: "Could not edit delivery" } } }, Modifier.fillMaxWidth()) }
}

@Composable fun VoucherScreen(deliveryId: Long, onUndo: () -> Unit, onEdit: () -> Unit = {}, vm: FeatureViewModel = hiltViewModel()) {
