        customer?.let { c -> ColdDeliveryCard(Modifier.fillMaxWidth()) { Column(Modifier.padding(13.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text(c.name, fontSize = 16.sp, fontWeight = FontWeight.Bold); Text(c.phone, color = ColdDeliveryColors.SecondaryText, fontSize = 11.sp); Text(c.address, color = ColdDeliveryColors.SecondaryText, fontSize = 10.sp, maxLines = 2) }; StatusChip(delivery?.status == DeliveryStatus.DELIVERED) }; Text(delivery?.let { day(it.deliveryDate) } ?: "", color = Gold, fontSize = 11.sp, fontWeight = FontWeight.Bold) } } }
        SectionHeading(stringResource(com.colddelivery.app.R.string.item_details))
        ColdDeliveryCard(Modifier.fillMaxWidth()) { Row(Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 9.dp), horizontalArrangement = Arrangement.SpaceBetween) { Text(stringResource(com.colddelivery.app.R.string.product), Modifier.weight(1f), color = ColdDeliveryColors.SecondaryText, fontSize = 9.sp); Text(stringResource(com.colddelivery.app.R.string.qty), Modifier.width(42.dp), color = ColdDeliveryColors.SecondaryText, fontSize = 9.sp); Text(stringResource(com.colddelivery.app.R.string.unit_price), Modifier.width(76.dp), color = ColdDeliveryColors.SecondaryText, fontSize = 9.sp); Text(stringResource(com.colddelivery.app.R.string.amount), Modifier.width(76.dp), color = ColdDeliveryColors.SecondaryText, fontSize = 9.sp) } }
        LazyColumn(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(7.dp)) { items(items) { item -> ColdDeliveryCard { Row(Modifier.fillMaxWidth().padding(12.dp), verticalAlignment = Alignment.CenterVertically) { Text(products.firstOrNull { it.id == item.productId }?.productName ?: stringResource(com.colddelivery.app.R.string.product), Modifier.weight(1f), fontWeight = FontWeight.Bold, fontSize = 11.sp, maxLines = 2); Text("${item.qty}", Modifier.width(42.dp), fontSize = 11.sp); Text(money(item.unitPrice), Modifier.width(76.dp), fontSize = 10.sp); Text(money(item.amount), Modifier.width(76.dp), color = DeepRed, fontSize = 10.sp, fontWeight = FontWeight.Bold, maxLines = 1) } } } }
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { MetricCard(stringResource(com.colddelivery.app.R.string.total_qty), "$totalQty ${stringResource(com.colddelivery.app.R.string.ctn)}", Modifier.weight(1f)); MetricCard(stringResource(com.colddelivery.app.R.string.total_price), money(totalAmount), Modifier.weight(1f)) }
        ColdDeliveryCard(Modifier.fillMaxWidth()) { Column(Modifier.padding(12.dp)) { Text(stringResource(com.colddelivery.app.R.string.note), color = Gold, fontWeight = FontWeight.Bold, fontSize = 11.sp); Text(customer?.note?.takeIf { it.isNotBlank() } ?: stringResource(com.colddelivery.app.R.string.no_note), color = ColdDeliveryColors.SecondaryText, fontSize = 11.sp) } }
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { PremiumOutlinedButton(stringResource(com.colddelivery.app.R.string.edit), onEdit, Modifier.weight(1f)); PremiumOutlinedButton(stringResource(com.colddelivery.app.R.string.undo), { scope.launch { vm.undo(deliveryId); onUndo() } }, Modifier.weight(1f)) }
    }
}

@Composable private fun MetricCard(label: String, value: String, modifier: Modifier = Modifier) { ColdDeliveryCard(modifier.heightIn(min = 78.dp)) { Column(Modifier.fillMaxWidth().padding(11.dp), verticalArrangement = Arrangement.spacedBy(3.dp)) { Text(label, color = ColdDeliveryColors.SecondaryText, fontSize = 10.sp); Text(value, color = DeepRed, fontSize = 15.sp, fontWeight = FontWeight.Bold, maxLines = 1) } } }

@Composable fun SettingsScreen(onLogin: () -> Unit, onBackup: () -> Unit = {}, vm: FeatureViewModel = hiltViewModel()) {
    val language by vm.language.collectAsState(); val threshold by vm.lowStockThreshold.collectAsState(); val context = LocalContext.current; var input by remember(threshold) { mutableStateOf(threshold.toString()) }
    PremiumPage { PremiumPageTitle("Settings", "Cold Delivery preferences"); ColdDeliveryCard { Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Text("Language", color = DeepRed, fontWeight = FontWeight.Bold); LanguageSegmentedControl(language, { vm.saveLanguage(it); LanguageManager.apply(context, it) }, Modifier.fillMaxWidth()); Text("Choose the language used throughout the app.", color = ColdDeliveryColors.SecondaryText, fontSize = 10.sp) } }; ColdDeliveryCard { Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Text("Stock alerts", color = DeepRed, fontWeight = FontWeight.Bold); Field(input, { input = it.filter(Char::isDigit) }, "Low-stock threshold", KeyboardType.Number); TextButton({ input.toIntOrNull()?.let(vm::saveThreshold) }) { Text("Save threshold", color = DeepRed, fontSize = 11.sp) } } }; ColdDeliveryCard { Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Text("Backup & restore", color = DeepRed, fontWeight = FontWeight.Bold); Text("Keep a local copy of your delivery data.", color = ColdDeliveryColors.SecondaryText, fontSize = 10.sp); PrimaryRedButton("Open Backup & Restore", onBackup, Modifier.fillMaxWidth()) } }; ColdDeliveryCard { Row(Modifier.fillMaxWidth().padding(12.dp), horizontalArrangement = Arrangement.SpaceBetween) { Text("App version", color = ColdDeliveryColors.SecondaryText); Text("1.0", fontWeight = FontWeight.Bold) } }; Spacer(Modifier.weight(1f)); PremiumOutlinedButton("Logout", onLogin, Modifier.fillMaxWidth()) }
}

@Composable fun BackupScreen(onBack: () -> Unit, vm: FeatureViewModel = hiltViewModel()) {
    val context = LocalContext.current; var status by remember { mutableStateOf<String?>(null) }; val create = rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/zip")) { uri -> if (uri != null) status = BackupManager(context, vm.databaseForBackup()).create(uri).fold({ "Backup created" }, { it.message ?: "Backup failed" }) }; val restore = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri -> if (uri != null) status = BackupManager(context, vm.databaseForBackup()).restore(uri).fold({ "Restore complete. Restart the app." }, { it.message ?: "Restore failed" }) }
    PremiumPage { PremiumPageTitle("Backup & Restore", "Protect your local delivery records"); ColdDeliveryCard { Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(7.dp)) { Text("Backup status", color = Gold, fontWeight = FontWeight.Bold); Text(status ?: "No backup action in this session", color = ColdDeliveryColors.SecondaryText, fontSize = 11.sp); Text("Local ZIP backup keeps database data portable.", color = ColdDeliveryColors.SecondaryText, fontSize = 10.sp) } }; PrimaryRedButton("Create Local Backup", { create.launch("cold_delivery_backup_" + System.currentTimeMillis() + ".zip") }, Modifier.fillMaxWidth()); PremiumOutlinedButton("Restore Local Backup", { restore.launch(arrayOf("application/zip")) }, Modifier.fillMaxWidth()); Text("Restore replaces local data and may require an app restart.", color = DeepRed, fontSize = 10.sp); Spacer(Modifier.weight(1f)); TextButton(onBack) { Text("Back", color = DeepRed) } }
}

@Composable fun LoginScreen(onLoggedIn: () -> Unit, vm: FeatureViewModel = hiltViewModel()) { var username by rememberSaveable { mutableStateOf("") }; var password by rememberSaveable { mutableStateOf("") }; PremiumPage { PremiumPageTitle("Cold Delivery", "Offline Delivery Management"); Field(username, { username = it }, "Username"); Field(password, { password = it }, "Password"); Spacer(Modifier.weight(1f)); PrimaryRedButton("Login", { if (username.isNotBlank() && password.isNotBlank()) onLoggedIn() }, Modifier.fillMaxWidth()) } }
@Composable fun AuthLoginScreen(onLoggedIn: () -> Unit, vm: AuthViewModel = hiltViewModel()) { var username by rememberSaveable { mutableStateOf("") }; var password by rememberSaveable { mutableStateOf("") }; var remember by rememberSaveable { mutableStateOf(true) }; var error by remember { mutableStateOf<String?>(null) }; val scope = rememberCoroutineScope(); PremiumPage { PremiumPageTitle("Cold Delivery", "Offline Delivery Management"); Field(username, { username = it }, "Username"); Field(password, { password = it }, "Password"); Row(verticalAlignment = Alignment.CenterVertically) { Checkbox(remember, { remember = it }); Text("Remember Me", fontSize = 12.sp) }; error?.let { Text(it, color = DeepRed) }; Spacer(Modifier.weight(1f)); PrimaryRedButton("Login", { scope.launch { if (vm.login(username, password, remember)) onLoggedIn() else error = vm.message.value } }, Modifier.fillMaxWidth()) } }
private fun FeatureViewModel.viewModelScopeLaunch(block: suspend () -> Unit) { kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main).launch { block() } }
